"""Write config/dse.toml for XenonRecomp from the decomp project's symbols.txt.

Every function dtk found (type:function in .init/.text, except the zero-padding
"gap_" entries) becomes a {address, size} entry, so XenonRecomp does not need
the Xbox 360 .pdata table.

Usage: python tools/make_config.py
"""
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SYMBOLS = ROOT.parent / "decomp" / "config" / "RZJE69" / "symbols.txt"
OUT = ROOT / "config" / "dse.toml"

HEADER = """# XenonRecomp - Dead Space: Extraction (Wii, RZJE69)
# Generated by tools/make_config.py from decomp/config/RZJE69/symbols.txt.
[main]
file_path = "../dol/main.elf"
out_directory_path = "../ppc"
# switch jump tables, from tools/make_switch_tables.py
switch_table_file_path = "dse_switch_tables.toml"

# The Wii emitter (gekko.cpp) expects every register to live in ctx.
skip_lr = false
skip_msr = false
ctr_as_local = false
xer_as_local = false
reserved_as_local = false
cr_as_local = false
non_argument_as_local = false
non_volatile_as_local = false

# Only the functions below (dtk's list). Gaps in .text hold data, like MetroTRK's
# instruction table at 0x80354890, and must not be recompiled as code.
declared_functions_only = true

functions = [
"""


def main():
    pat = re.compile(r"^(\S+) = \.(init|text):0x([0-9A-F]{8}); // type:function size:0x([0-9A-F]+)")
    funcs = []
    for line in SYMBOLS.read_text().splitlines():
        m = pat.match(line)
        if m and not m.group(1).startswith("gap_"):
            funcs.append((int(m.group(3), 16), int(m.group(4), 16)))
    funcs.sort()

    # CodeWarrior register save/restore helpers (_savefpr_14.._restgpr_31) are labels inside
    # one function, and code calls straight into the middle of it. Each entry label becomes
    # its own function that runs to the end of the helper.
    label = re.compile(r"^(_(?:save|rest)(?:fpr|gpr)_\d+) = \.text:0x([0-9A-F]{8}); // type:label")
    starts = set(a for a, _ in funcs)
    extra = 0
    for line in SYMBOLS.read_text().splitlines():
        m = label.match(line)
        if not m:
            continue
        addr = int(m.group(2), 16)
        if addr in starts:
            continue
        parent = max((f for f in funcs if f[0] <= addr), key=lambda f: f[0])
        funcs.append((addr, parent[0] + parent[1] - addr))
        extra += 1
    funcs.sort()
    print(f"{extra} save/restore helper entry points")
    body = "".join(f"    {{ address = 0x{a:08X}, size = 0x{s:X} }},\n" for a, s in funcs)
    OUT.parent.mkdir(exist_ok=True)
    OUT.write_bytes((HEADER + body + "]\n").encode())
    print(f"{len(funcs)} functions -> {OUT}")


if __name__ == "__main__":
    main()
